#ch-branches {
  --ink: var(--ink, #0F172A);
  --muted: var(--muted, #64748B);
  --accent: var(--accent, #06B6D4);
  --warm: var(--warm, #F59E0B);
  --line: var(--line, #E2E8F0);
  --paper: var(--paper, #F8FAFC);
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem 1rem;
  line-height: 1.6;
}

#ch-branches h2 {
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

#ch-branches .lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 70ch;
  margin-bottom: 2rem;
}

/* Trilemma Gate Layout */
#ch-branches .trilemma-gate {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
}

#ch-branches .gate-node {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1.5rem;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

#ch-branches .gate-node:hover,
#ch-branches .gate-node.active {
  border-color: var(--accent);
  box-shadow: 0 4px 12px rgba(6, 182, 212, 0.1);
  transform: translateY(-2px);
}

#ch-branches .gate-node.active {
  background: rgba(6, 182, 212, 0.03);
}

#ch-branches .gate-symbol {
  font-size: 2.5rem;
  font-weight: 300;
  color: var(--accent);
  margin-bottom: 0.5rem;
  font-family: 'Times New Roman', serif;
}

#ch-branches .gate-node h3 {
  font-size: 1.25rem;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

#ch-branches .gate-desc {
  font-size: 0.95rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

#ch-branches .btn-expand {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 0.4rem 0.8rem;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
  transition: background 0.2s;
}

#ch-branches .btn-expand:hover {
  background: var(--line);
}

/* Evidence Panel */
#ch-branches .evidence-panel {
  background: #fff;
  border-left: 4px solid var(--accent);
  padding: 1.5rem;
  margin-bottom: 2rem;
  border-radius: 0 8px 8px 0;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
  display: none;
}

#ch-branches .evidence-panel.visible {
  display: block;
  animation: fadeIn 0.3s ease;
}

#ch-branches .panel-content h4 {
  margin-top: 0;
  color: var(--ink);
  font-size: 1.1rem;
}

#ch-branches .panel-content p {
  font-size: 1rem;
  color: #334155;
  margin-bottom: 1rem;
}

#ch-branches .source-trail {
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--line);
  font-size: 0.85rem;
  color: var(--muted);
}

#ch-branches .source-btn {
  background: none;
  border: none;
  color: var(--accent);
  text-decoration: underline;
  cursor: pointer;
  padding: 0;
  font-size: inherit;
  margin-right: 0.5rem;
}

/* Interaction Zone */
#ch-branches .interaction-zone {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1.5rem;
  margin-top: 2rem;
}

#ch-branches .controls {
  margin-bottom: 1rem;
  display: flex;
  gap: 1.5rem;
}

#ch-branches .controls label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.95rem;
  cursor: pointer;
}

#ch-branches .stack-viz-container {
  position: relative;
  margin: 1rem 0;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #fafafa;
}

#ch-branches canvas {
  display: block;
  width: 100%;
  height: auto;
}

#ch-branches .stack-legend {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 0.5rem;
  justify-content: center;
}

#ch-branches .legend-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

#ch-branches .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

#ch-branches .dot.base { background: #0F172A; }
#ch-branches .dot.sim { background: #06B6D4; }
#ch-branches .dot.shadow { background: #94A3B8; }

#ch-branches .math-readout {
  font-family: 'Courier New', monospace;
  background: #f1f5f9;
  padding: 1rem;
  border-radius: 4px;
  font-size: 0.9rem;
  margin-top: 1rem;
}

#ch-branches .note {
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 0.5rem;
}

#ch-branches .btn-reset {
  margin-top: 1rem;
  background: var(--ink);
  color: #fff;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
}

#ch-branches .btn-reset:hover {
  opacity: 0.9;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 600px) {
  #ch-branches .trilemma-gate {
    grid-template-columns: 1fr;
  }
  #ch-branches .controls {
    flex-direction: column;
    gap: 0.5rem;
  }
}

