(function() {
  'use strict';

  const scopeId = 'ch-branches';
  const container = document.getElementById(scopeId);
  if (!container) return;

  const gates = container.querySelectorAll('.gate-node');
  const evidencePanel = container.querySelector('#evidence-display');
  const panelTitle = container.querySelector('#panel-title');
  const panelBody = container.querySelector('#panel-body');
  const panelSources = container.querySelector('#panel-sources');
  const simZone = container.querySelector('#sim-stack-zone');
  const canvas = container.querySelector('#stack-canvas');
  const ctx = canvas ? canvas.getContext('2d') : null;
  const ratioDisplay = container.querySelector('#ratio-display');
  const resetBtn = container.querySelector('#reset-sim');
  const modeRadios = container.querySelectorAll('input[name="sim-mode"]');

  // Data from nodes
  const nodeData = {
    'interpret-doom': {
      title: '解释分支一：大灭绝 (DOOM)',
      content: '若命题 (1) 为真 (Pf ≈ 0)，意味着人类极可能在达到后人类阶段前灭绝。这并不必然意味着近期灭绝，但暗示了危险技术（如分子纳米技术）或文明崩溃的高风险。除非我们有特殊证据表明自己是幸运的例外，否则应假设面临同样的灭绝概率。',
      sources: ['S059', 'S062']
    },
    'interpret-convergence': {
      title: '解释分支二：强收敛 (Convergence)',
      content: '若命题 (2) 为真 (fI ≈ 0)，意味着几乎所有后人类文明都因伦理禁令、兴趣丧失或社会结构变化而不运行祖先模拟。这要求后人类社会与人类社会存在本质差异，缺乏拥有完整人类欲望谱系的独立个体。',
      sources: ['S062', 'S065']
    },
    'interpret-sim-reality': {
      title: '解释分支三：模拟现实 (Simulation Reality)',
      content: '若命题 (3) 为真 (f_sim ≈ 1)，则我们几乎肯定生活在模拟中。观测到的宇宙只是物理存在总量的一小部分。运行模拟的计算机所在的宇宙，其物理定律可能与我们观测到的完全不同。',
      sources: ['S065', 'S066']
    }
  };

  const sourceMap = window.paperMindData?.sources || {};

  function renderSources(sourceIds) {
    if (!sourceIds || sourceIds.length === 0) {
      panelSources.innerHTML = '';
      return;
    }
    const html = sourceIds.map(id => {
      const src = sourceMap[id];
      const label = src ? `p.${src.page}` : '来源未知';
      return `<button type="button" class="source-btn" data-source="${id}">原文 · ${label}</button>`;
    }).join('');
    panelSources.innerHTML = html;
  }

  function activateGate(nodeId) {
    gates.forEach(g => g.classList.remove('active'));
    const activeGate = container.querySelector(`.gate-node[data-node="${nodeId}"]`);
    if (activeGate) activeGate.classList.add('active');

    const data = nodeData[nodeId];
    if (!data) return;

    panelTitle.textContent = data.title;
    panelBody.innerHTML = `<p>${data.content}</p>`;
    renderSources(data.sources);
    evidencePanel.classList.add('visible');

    if (nodeId === 'interpret-sim-reality') {
      simZone.style.display = 'block';
      drawStack('full');
    } else {
      simZone.style.display = 'none';
    }
  }

  gates.forEach(gate => {
    gate.addEventListener('click', () => {
      const nodeId = gate.dataset.node;
      activateGate(nodeId);
    });

    const btn = gate.querySelector('.btn-expand');
    if (btn) {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const nodeId = gate.dataset.node;
        activateGate(nodeId);
        // Scroll to evidence panel smoothly
        evidencePanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    }
  });

  // Canvas Visualization Logic
  function drawStack(mode) {
    if (!ctx || !canvas) return;
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    const baseColor = '#0F172A';
    const simColor = '#06B6D4';
    const shadowColor = '#94A3B8';

    // Draw Base Reality
    ctx.fillStyle = baseColor;
    ctx.fillRect(20, h - 60, w - 40, 40);
    ctx.fillStyle = '#fff';
    ctx.font = '12px sans-serif';
    ctx.fillText('Basement Reality (Fundamental)', 30, h - 35);

    if (mode === 'full') {
      // Draw stacked full simulations
      let y = h - 80;
      for (let i = 0; i < 3; i++) {
        ctx.fillStyle = simColor;
        ctx.globalAlpha = 0.8 - (i * 0.2);
        ctx.fillRect(40 + (i * 10), y - 40, w - 60 - (i * 20), 30);
        ctx.globalAlpha = 1.0;
        ctx.fillStyle = '#0F172A';
        ctx.fillText(`Simulation Level ${i + 1}`, 50 + (i * 10), y - 20);
        y -= 50;
      }
      ratioDisplay.textContent = '1 : 1 (每层均为完整意识)';
    } else {
      // Draw Shadow People mode
      let y = h - 80;
      ctx.fillStyle = shadowColor;
      ctx.globalAlpha = 0.6;
      ctx.fillRect(40, y - 40, w - 60, 30);
      ctx.globalAlpha = 1.0;
      ctx.fillStyle = '#0F172A';
      ctx.fillText('Shadow Layer (Zombies/Background)', 50, y - 20);

      // Highlight single conscious entity
      ctx.fillStyle = simColor;
      ctx.beginPath();
      ctx.arc(w / 2, y - 25, 8, 0, Math.PI * 2);
      ctx.fill();

      ratioDisplay.textContent = '1 : 100,000,000,000 (需极大数量倍数)';
    }
  }

  modeRadios.forEach(radio => {
    radio.addEventListener('change', (e) => {
      drawStack(e.target.value);
    });
  });

  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      modeRadios[0].checked = true;
      drawStack('full');
      simZone.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }

  // Initial State
  evidencePanel.classList.remove('visible');
  simZone.style.display = 'none';

})();
